-- Diagnostic only: the installed GameCore exports read-only Great Work access, but no known CreateGreatWork binding.
local names={'GetGreatWorks','CreateGreatWork','GetGreatWorkDataFromIndex','GetGreatWorkPlayer','GetGreatPeople'}
local out={}
for _,name in ipairs(names) do local ok,value=pcall(function() return Game[name] end);out[#out+1]=name..'='..(ok and type(value) or 'unreadable') end
local city=assert(Players[Game.GetLocalPlayer()]:GetCities():GetCapitalCity())
for _,name in ipairs({'CreateGreatWork','CreateGreatWorkInSlot','SetGreatWorkInSlot','GetGreatWorkInSlot'}) do local ok,value=pcall(function() return city:GetBuildings()[name] end);out[#out+1]='CityBuildings.'..name..'='..(ok and type(value) or 'unreadable') end
print('[JAC_ARTWORK_CORE_API_DIAG] '..table.concat(out,' '))
return table.concat(out,' ')

-- Read actual published slots and provenance. This step does not claim MOVE success.
local out={}
local art={GREATWORKOBJECT_SCULPTURE=true,GREATWORKOBJECT_LANDSCAPE=true,GREATWORKOBJECT_PORTRAIT=true,GREATWORKOBJECT_RELIGIOUS=true}
local counts={artifact=0,art=0}
for _,owner in ipairs(PlayerManager.GetAliveIDs()) do local player=Players[owner];if player then for _,city in player:GetCities():Members() do local b=city:GetBuildings();for building in GameInfo.Buildings() do if b:HasBuilding(building.Index) then for slot=0,b:GetNumGreatWorkSlots(building.Index)-1 do local index=b:GetGreatWorkInSlot(building.Index,slot);if index and index>=0 then local kind=assert(GameInfo.GreatWorks[b:GetGreatWorkTypeFromIndex(index)]).GreatWorkObjectType;if kind=='GREATWORKOBJECT_ARTIFACT' or art[kind] then local group=kind=='GREATWORKOBJECT_ARTIFACT' and 'artifact' or 'art';counts[group]=counts[group]+1;out[#out+1]={Group=group,Index=index,Owner=owner,City=city:GetID(),Building=building.BuildingType,Slot=slot,Created=b:GetTurnFromIndex(index),Creator=b:GetCreatorNameFromIndex(index),CreatedBy=Game.GetGreatWorkPlayer(index)} end end end end end end end end
print('[JAC_ARTWORK_EXISTING_SLOTS] artifact='..counts.artifact..' art='..counts.art)
for _,row in ipairs(out) do print('[JAC_ARTWORK_EXISTING_SLOT] group='..row.Group..' index='..row.Index..' owner='..row.Owner..' city='..row.City..' building='..row.Building..' slot='..row.Slot..' turn='..tostring(row.Created)..' creator='..tostring(row.Creator)..' createdBy='..tostring(row.CreatedBy)) end
return 'diagnosis only: artifact='..counts.artifact..' art='..counts.art..'; physical MOVE not yet tested'
